# ===============================
# 1. 주기성 (Periodicity) 검증 함수
# ===============================
def detect_periodicity(prices, min_period=2, max_period=30):
    best_period = None
    best_corr = -np.inf
    results = []
    for t in range(min_period, max_period + 1):
        if len(prices) > t:
            corr = np.corrcoef(prices[:-t], prices[t:])[0, 1]
            results.append((t, corr))
            if corr > best_corr:
                best_corr = corr
                best_period = t
    print("=== Periodicity Detection ===")
    for t, corr in results:
        print(f"Period {t}: Autocorrelation = {corr:.4f}")
    print(f"Best period: {best_period} with correlation {best_corr:.4f}\n")

# ===============================
# 2. 평균회귀 (Mean Reversion) 검증 함수
# ===============================
def detect_mean_reversion(prices, min_window=3, max_window=20):
    best_window = None
    best_corr = np.inf  # we look for most negative autocorrelation
    results = []
    for w in range(min_window, max_window + 1):
        if len(prices) >= w:
            # Compute moving average
            ma = np.convolve(prices, np.ones(w) / w, mode='valid')
            # Align deviations: index from w-1 to end
            deviations = prices[w - 1:] - ma
            if len(deviations) > 1:
                lag1_corr = np.corrcoef(deviations[:-1], deviations[1:])[0, 1]
                results.append((w, lag1_corr))
                if lag1_corr < best_corr:
                    best_corr = lag1_corr
                    best_window = w
    print("=== Mean Reversion Detection ===")
    for w, corr in results:
        print(f"Window {w}: Lag-1 Autocorrelation of deviations = {corr:.4f}")
    print(f"Best window for mean reversion: {best_window} with autocorrelation {best_corr:.4f}\n")

# ===============================
# 3. 스텝 체인지 (Step Change) 검증 함수
# ===============================
def detect_step_change(prices, min_window=3, max_window=10):
    best_window = None
    best_change = 0
    best_index = None
    for w in range(min_window, max_window + 1):
        for i in range(w, len(prices) - w):
            mean_before = np.mean(prices[i - w:i])
            mean_after = np.mean(prices[i:i + w])
            change = abs(mean_after - mean_before)
            if change > best_change:
                best_change = change
                best_index = i
                best_window = w
    print("=== Step Change Detection ===")
    print(f"Best window = {best_window}, Maximum mean change = {best_change:.4f} at index {best_index}\n")

# ===============================
# 4. 스파이크 후 회복 (Spike and Recovery) 검증 함수
# ===============================
def detect_spike_recovery(prices, window=5, recovery_gap=2):
    prices = np.array(prices)
    # 계산을 위해 rolling mean과 rolling std를 구함 (window 길이)
    rolling_mean = np.convolve(prices, np.ones(window) / window, mode='valid')
    rolling_std = np.array([np.std(prices[i - window + 1:i + 1]) for i in range(window - 1, len(prices))])
    
    thresholds = np.arange(1.0, 3.1, 0.5)
    best_threshold = None
    best_metric = -np.inf
    print("=== Spike and Recovery Detection ===")
    for thresh in thresholds:
        recovery_ratios = []
        for i in range(len(rolling_mean) - recovery_gap):
            idx = i + window - 1  # index in original prices corresponding to rolling_mean[i]
            deviation = prices[idx] - rolling_mean[i]
            if abs(deviation) > thresh * rolling_std[i]:
                # spike detected, measure recovery over next recovery_gap steps if available
                if idx + recovery_gap < len(prices):
                    recovery = prices[idx + recovery_gap] - prices[idx]
                    ratio = recovery / deviation if deviation != 0 else 0
                    recovery_ratios.append(ratio)
        if recovery_ratios:
            avg_ratio = np.mean(recovery_ratios)
            print(f"Threshold {thresh:.1f}: Average recovery ratio = {avg_ratio:.4f}")
            if abs(avg_ratio) > best_metric:
                best_metric = abs(avg_ratio)
                best_threshold = thresh
        else:
            print(f"Threshold {thresh:.1f}: No spikes detected")
    print(f"Best threshold: {best_threshold} with average recovery ratio magnitude {best_metric:.4f}\n")

# ===============================
# 5. 추세 전환 (Trend Reversal) 검증 함수
# ===============================
def detect_trend_reversal(prices, min_window=3, max_window=10):
    best_window = None
    best_diff = 0
    best_index = None
    for w in range(min_window, max_window + 1):
        for i in range(w, len(prices) - w):
            x = np.arange(w)
            slope_left = np.polyfit(x, prices[i - w:i], 1)[0]
            slope_right = np.polyfit(x, prices[i:i + w], 1)[0]
            diff = abs(slope_right - slope_left)
            if diff > best_diff:
                best_diff = diff
                best_index = i
                best_window = w
    print("=== Trend Reversal Detection ===")
    print(f"Best window = {best_window}, Maximum slope difference = {best_diff:.4f} at index {best_index}\n")

